[tool_use Bash] # Configure nginx to proxy to noVNC on port 80
cat > /etc/nginx/sites-available/novnc <<'EOF'
server {
    listen 80 default_server;
    server_name _;

    location / {
        proxy_pass http://localhost:6080/;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 86400;
    }
}
EOF

# Remove default site and enable novnc
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/novnc /etc/nginx/sites-enabled/novnc
nginx -t 2>&1 && (nginx -s stop 2>/dev/null; sleep 0.5; nginx) 2>&1

[tool_use Bash] # Try a different nginx config - serve noVNC files directly and proxy websocket
cat > /etc/nginx/sites-available/novnc <<'EOF'
server {
    listen 80 default_server;
    server_name _;

    root /usr/share/novnc;
    index vnc.html index.html;

    location /websockify {
        proxy_pass http://127.0.0.1:6080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }

    location / {
        try_files $uri $uri/ @proxy;
    }

    location @proxy {
        proxy_pass http://127.0.0.1:6080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400;
    }
}
EOF

